from pathlib import Path
import re, csv, json, shutil, html

raise SystemExit('Retired initial draft builder. Edit the canonical housing page or use polish_housing.py.')

ROOT = Path(__file__).resolve().parents[1]
TARGET = Path(r'C:\Users\justi\OneDrive\Documents\Career\Portfolio')
SOURCE = ROOT / 'references/toronto-housing/Toronto Housing - PC Handoff'
DRAFT = SOURCE / '02 - Portfolio Case Study Draft'
OUT = TARGET / 'housing'
OUT.mkdir(exist_ok=True)
original = (DRAFT / 'index.html').read_text(encoding='utf-8')
map_svg = re.search(r'<svg viewBox="0 0 980 420".*?</svg>', original, re.S).group()
colors = ['#F6DCD3','#EBAA99','#DA7864','#B8392A','#842B24']
def color_path(m):
    path = m.group()
    pct = float(re.search(r': ([\d.]+)%', path).group(1))
    level = min(4, max(0, int((pct-20)//10)))
    path = re.sub(r'fill="#[a-fA-F0-9]+"', f'fill="{colors[level]}"', path)
    name = html.unescape(re.search(r'<title>(.*?): ', path).group(1))
    return path.replace('<path ', '<path data-name="'+html.escape(name, quote=True)+'" ')
map_svg = re.sub(r'<path .*?</path>', color_path, map_svg)
(OUT/'pressure-map.svg').write_text(map_svg.replace('<svg ', '<svg xmlns="http://www.w3.org/2000/svg" ', 1),encoding='utf-8')
shutil.copyfile(DRAFT/'assets/data-2011.csv', OUT/'data-2011.csv')
shutil.copyfile(SOURCE/'01 - Final Project/Who Can Afford to Rent in Toronto - Final.pdf', OUT/'original-presentation.pdf')
rows = list(csv.DictReader((OUT/'data-2011.csv').open(encoding='utf-8-sig')))
data = [dict(name=r['Neighbourhood Name'],rent=float(r['Average Monthly Rental Cost']),pressure=round(float(r['Renters Spending 30 Percent or More'])*100,1)) for r in rows]
base = (TARGET/'tstar.html').read_text(encoding='utf-8')
head = base[:base.index('<style>')].replace('<title>TStar Case Study</title>','<title>Toronto housing — Justin Dao</title>')
head = re.sub(r'<meta name="description"[^>]*>', '<meta name="description" content="What rental prices leave out: a visual exploration of housing pressure across 140 Toronto neighbourhoods, by Justin Dao.">', head)
toggle = re.search(r'<button class="tbtn fx".*?</button>',base,re.S).group()
links = [('overview','overview'),('question','the question'),('solution','the story'),('map','neighbourhoods'),('cost','rental costs'),('context','housing support'),('process','my process'),('learning','learning')]
rail = '<aside class="side" aria-label="Case study sections"><a class="back" href="index.html#work" aria-label="Back to work">←</a><ul>'+''.join(f'<li><a href="#{id}">{label}</a></li>' for id,label in links)+'</ul></aside>'
def sec(id,label,title,copy):
    return f'<section id="{id}"><p class="eb">{label}</p><h2>{title}</h2><p>{copy}</p>'
def metric(title,a,b,maxval,unit='',prefix=''):
    return f'<div class="compare-row"><h3>{title}</h3><div class="metric"><span>Regent Park</span><div><i style="width:{a/maxval*100:.2f}%"></i></div><b>{prefix}{a:,.0f}{unit}</b></div><div class="metric second"><span>South Parkdale</span><div><i style="width:{b/maxval*100:.2f}%"></i></div><b>{prefix}{b:,.0f}{unit}</b></div></div>' if not unit else f'<div class="compare-row"><h3>{title}</h3><div class="metric"><span>Regent Park</span><div><i style="width:{a}%"></i></div><b>{a:.1f}%</b></div><div class="metric second"><span>South Parkdale</span><div><i style="width:{b}%"></i></div><b>{b:.1f}%</b></div></div>'
body = '''<div class="topnav"><a href="index.html#work">← Work</a><span>Toronto housing</span></div><main class="main">
<header id="overview"><div class="hero-art"><div class="hero-kicker">TORONTO · 2011 RENTER DATA</div><div class="hero-line">The highest rent.<br><span>The greatest pressure?</span></div><img src="housing/pressure-map.svg" alt="Toronto neighbourhoods shaded by the share of renters spending at least 30% of income on housing"><div class="chapters"><span>01 locate</span><span>02 compare</span><span>03 question</span></div></div><h1>Expensive rent.<br>A bigger story.</h1><p class="lead">I explored 140 Toronto neighbourhoods to understand what rental prices leave out. The story moved from the cost of housing to the share of renters struggling to afford it.</p><dl class="meta"><div><dt>Context</dt><dd>Academic data storytelling</dd></div><div><dt>My work</dt><dd>Data preparation, analysis and visual narrative</dd></div><div><dt>Tools</dt><dd>Excel · Tableau</dd></div></dl><p class="historical">A historical study using 2011 neighbourhood data, with a separate 2016 overview. It does not describe today’s rental market.</p></header>
'''
body += sec('question','The problem','A price ranking only tells half the story.','I started by asking where housing was most expensive. But a rental bill alone cannot tell me how hard it is to pay. I narrowed the question: how do rental costs, income and housing support relate to renter housing pressure?')
body += '''<div class="panel budget"><div class="bill"><span>ILLUSTRATIVE MONTHLY HOUSING BILL</span><strong>$1,200</strong><p>Same cost. Different breathing room.</p></div><div class="budget-bars"><div><div class="bar-label"><b>$3,000 income</b><span>40% for housing</span></div><div class="track"><i style="width:40%"></i></div></div><div><div class="bar-label"><b>$6,000 income</b><span>20% for housing</span></div><div class="track"><i style="width:20%"></i></div></div></div><p class="caption">Illustrative budgets, not observed households. Income is before tax.</p></div></section>'''
body += sec('solution','The solution','One question. Three views of the evidence.','I built a visual data story connecting rental costs, income and housing support across Toronto neighbourhoods.')
body += '''<div class="features"><a href="#map"><span class="number">01 <i>locate</i></span><img src="housing/pressure-map.svg" alt="Map of Toronto renter pressure"><h3>Where is the pressure?</h3><p>A map shows the share of renters above the 30% threshold.</p></a><a href="#cost"><span class="number">02 <i>compare</i></span><div class="mini-points" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><h3>Does higher rent mean more pressure?</h3><p>A dot chart challenges a simple price ranking.</p></a><a href="#context"><span class="number">03 <i>add context</i></span><div class="mini-bars" aria-hidden="true"><i></i><i></i><i></i><i></i></div><h3>What else belongs in the picture?</h3><p>Two neighbourhoods bring income and support into view.</p></a></div></section>'''
body += sec('map','01 / Locate the pressure','The pressure does not fall evenly.','Here, housing pressure means the share of renters spending at least 30% of before-tax income on housing. Darker red means more renters cross that threshold.')
body += '<div class="panel map-panel"><div class="chart-top"><span class="number">140 historical neighbourhoods · 2011</span><label for="area">Explore a neighbourhood</label><select id="area">'+''.join(f'<option{ " selected" if r["name"]=="Newtonbrook West" else ""}>{html.escape(r["name"])}</option>' for r in data)+'</select></div><div class="map-wrap">'+map_svg+'</div><div class="legend"><span>Under 30%</span>'+''.join(f'<i style="background:{c}"></i>' for c in colors)+'<span>60%+</span></div><div id="area-result" class="area-result" aria-live="polite"></div></div><p class="caption">The map locates pressure. It does not explain what caused it. Historical boundaries: the 140-neighbourhood geography used in the supplied data.</p></section>'
body += sec('cost','02 / Compare rental costs','Higher rent did not always mean greater pressure.','Each dot is one neighbourhood. Moving right means higher rental costs; moving up means more renters spending at least 30% of income on housing.')
body += '''<div class="panel scatter-panel"><p class="chart-heading">Rental cost and renter pressure · 2011</p><div id="scatter" role="img" aria-label="Scatterplot of average monthly rental housing costs and the share of renters above the 30% threshold across 140 neighbourhoods. Kingsway South: $1,640 and 36.1%; Newtonbrook West: $1,135 and 60.3%."></div><div class="plot-key"><span><i></i>All neighbourhoods</span><span><i></i>Newtonbrook West / Kingsway South</span></div></div><div class="pair"><div><p class="number">Newtonbrook West</p><strong>$1,135<span> / month</span></strong><p><b>60.3%</b> of renters above the threshold</p></div><div><p class="number">Kingsway South</p><strong>$1,640<span> / month</span></strong><p><b>36.1%</b> of renters above the threshold</p></div></div><p class="caption">Average rental housing costs include applicable utilities. These neighbourhood measures describe an association, not individual renter budgets.</p></section>'''
body += sec('context','03 / Add context','Lower income. Less pressure. What else is different?','Regent Park had lower median household income than South Parkdale, yet lower rental costs and fewer renters above the threshold. It also had a much larger share of subsidized tenants.')
body += '<div class="panel comparison">'+metric('Median monthly household income',2681,2967,4000,prefix='$')+metric('Average monthly rental housing cost',631,865,1200,prefix='$')+metric('Renters in subsidized housing',64.6,17.9,100,unit='%')+metric('Renters spending 30%+ of income on housing',26.8,48.6,100,unit='%')+'</div>'
body += '''<div class="finding"><strong>21.8<span>percentage points</span></strong><p>The gap in renter pressure between these two neighbourhoods. Housing support and lower costs offer context, but this comparison does not prove a cause.</p></div><p class="caption">2011 data. Income covers all households, including owners, and refers to 2010 before-tax income. Rental costs, support and pressure cover renters. The measures have different populations; dividing these area-level figures would not give an observed renter budget.</p></section>'''
body += sec('process','Behind the work','I changed the question before polishing the charts.','The work was about choosing what the data could support, then giving each visual a clear job.')
body += '''<div class="process"><div><span class="number">01</span><h3>Narrow the question</h3><p>I dropped willingness to pay: the data does not measure why someone chooses a neighbourhood.</p></div><div><span class="number">02</span><h3>Prepare and explore</h3><p>I organized the cleaned data by neighbourhood in Excel and explored the measures in Tableau.</p></div><div><span class="number">03</span><h3>Choose the right view</h3><p>The map locates the pressure. The dot chart compares cost and pressure. Paired bars add context.</p></div><div><span class="number">04</span><h3>Edit the story</h3><p>I moved from broad chart titles to takeaway headlines, with units and population definitions beside the evidence.</p></div></div><details><summary>Why the 2016 overview stays separate</summary><p>The supplied 2016 overview reports 36.6% of assessed Toronto households spending at least 30% of income on housing. It includes owners and renters. The 2011 analysis here covers renters only.</p><p>These are different populations. Connecting them with a trend line would imply a change in renter affordability that the supplied data cannot establish.</p></details></section>'''
body += sec('learning','What I learned','A clearer question makes a stronger data story.','The useful finding was not a list of expensive neighbourhoods. It was seeing why the same price-based explanation did not fit every part of the city.')
body += '''<div class="lessons"><div><h3>Keep the population visible</h3><p>All-household income is useful context. It is not a measure of renters’ actual income.</p></div><div><h3>Let comparisons raise questions</h3><p>Regent Park and South Parkdale make support visible without claiming that one factor explains the gap.</p></div></div><h3 class="next-title">What I would do next</h3><p>I would use a newer, consistent dataset with renter-specific income and comparable boundaries before making a time comparison.</p><div class="downloads"><a class="button" href="housing/original-presentation.pdf" target="_blank" rel="noopener">View the original presentation ↗</a><a href="housing/data-2011.csv" download>Explore the cleaned data ↓</a></div></section><footer><p>Sources: supplied City of Toronto neighbourhood profiles and historical boundaries. This is an academic analysis, not a causal study.</p><div><a href="https://open.toronto.ca/dataset/neighbourhood-profiles/">Neighbourhood profiles ↗</a><a href="https://open.toronto.ca/dataset/neighbourhoods/">Historical boundaries ↗</a></div></footer><a class="next-project" href="instacart.html"><span>Next project<br><b>Grocery recommendations</b></span><span>→</span></a></main>'''
